package com.yeyamo_mobile.api.feed_service.application;import org.springframework.boot.context.properties.ConfigurationProperties;import org.springframework.stereotype.Component;import java.util.*;
@Component@ConfigurationProperties(prefix="yeyamo.feed.mix")public class FeedMixProperties{private Map<String,Double>weights=new HashMap<>(Map.of("SOCIAL",1d,"PLACE",1d,"EVENT",1d,"CULTURE_CONTENT",1d,"LANGUAGE_LESSON",1d,"ARTWORK",1d,"CULTURE_CHALLENGE",1d,"ARTISAN",1d));private double localCityWeight;private double countryWeight;private double africaDiscoveryWeight;private double followingWeight;private double cultureWeight;private double eventsWeight;private double artworkWeight;public Map<String,Double>getWeights(){return weights;}public void setWeights(Map<String,Double>w){weights=w;}public double weight(String type){return Math.max(0,weights.getOrDefault(type,1d));}public double getLocalCityWeight(){return localCityWeight;}public void setLocalCityWeight(double v){localCityWeight=Math.max(0,v);}public double getCountryWeight(){return countryWeight;}public void setCountryWeight(double v){countryWeight=Math.max(0,v);}public double getAfricaDiscoveryWeight(){return africaDiscoveryWeight;}public void setAfricaDiscoveryWeight(double v){africaDiscoveryWeight=Math.max(0,v);}public double getFollowingWeight(){return followingWeight;}public void setFollowingWeight(double v){followingWeight=Math.max(0,v);}public double getCultureWeight(){return cultureWeight;}public void setCultureWeight(double v){cultureWeight=Math.max(0,v);}public double getEventsWeight(){return eventsWeight;}public void setEventsWeight(double v){eventsWeight=Math.max(0,v);}public double getArtworkWeight(){return artworkWeight;}public void setArtworkWeight(double v){artworkWeight=Math.max(0,v);}}
